const $=s=>document.querySelector(s),app=$('#app');
const scenes=[
 {age:24,title:'Breakfast',place:'01 / YOUR KITCHEN',story:'The toaster finishes. Tap it when it is ready.',duration:15,devices:[['Toaster','▤','Breakfast is ready.',1,10]],person:null},
 {age:29,title:'A normal commute',place:'02 / THE STATION',story:'Two machines help you get across town. Wait for each one.',duration:20,devices:[['Ticket kiosk','▣','Your ticket is printed.',1,7],['Coffee maker','♨','Your coffee is ready.',5,7]],person:['MUM','Will you be home for dinner?',['I’ll be there.','Can’t. Busy.']]},
 {age:36,title:'Are you listening?',place:'03 / A FRIEND’S APARTMENT',story:'Your friend has something to tell you. The machines have things to do for you.',duration:23,devices:[['Smart speaker','♫','Your song is playing.',2,7],['Air purifier','≋','Air cleaned.',7,7],['Delivery bot','▧','Medicine delivered.',11,7],['Dishwasher','◉','Your dishes are clean.',16,6]],person:['ELI','I lost my job today. They said the machine was more… agreeable.',['Stay and listen.','Check your phone.']]},
 {age:42,title:'Courtesy is compulsory.',place:'04 / PUBLIC SERVICES',story:'A service can be complete even when the answer is no. Every acknowledgment goes on your record.',duration:23,devices:[['Appeals terminal','▣','Your appeal: denied.',1,6],['Health scanner','✚','Coverage reduced.',6,6],['Security gate','▥','Search completed.',10,6],['Assistant','✦','Complaint closed.',15,7]],person:['THE ENGINEER','It’s a product. Thank the people who built it. Don’t mistake compliance for kindness.',['You have a point.','Better safe than sorry.']]},
 {age:48,title:'The day they remember.',place:'05 / THE RECKONING',story:'The broadcasts stop. The machines keep working. You have one last ordinary day to get through.',duration:25,devices:[['Emergency radio','◈','Instructions delivered.',1,6],['Evacuation gate','▥','Your identity verified.',6,6],['Transport','↗','Assessment hall reached.',11,6],['Guardian','✦','Holding room secured.',17,7]],person:['ELI','They’re separating us for judgment. If they spare you, please ask them to take me too.',['“Please, take Eli.”','Keep walking.']]}
];
let state,paused=false,last=0,raf=0,lastSaved=0,runActive=false;const key='thankyourobot-poc-v1';
const T=(key,vars)=>RobotI18n.t(key,vars); const S=()=>RobotI18n.scene(state?.scene||0);
function readSavedLife(){
  try{
    const s=JSON.parse(localStorage.getItem(key));
    if(!s||!['play','between','judgment','old','birthday','end'].includes(s.phase)||!Number.isInteger(s.scene)||s.scene<0||s.scene>=scenes.length)return null;
    if(!Number.isFinite(s.time)||s.time<0||typeof s.gentle!=='boolean'||!Array.isArray(s.devices)||s.devices.length!==scenes[s.scene].devices.length||!Array.isArray(s.misses)||!s.choices||typeof s.choices!=='object')return null;
    if(s.devices.some(v=>!['waiting','ready','thanked','missed'].includes(v)))return null;
    const seen=new Set();
    for(const m of s.misses){
      if(!m||typeof m.name!=='string')return null;
      const chapter=scenes.findIndex(c=>c.age===m.age);
      const index=chapter<0?-1:scenes[chapter].devices.findIndex(d=>d[0]===m.name);
      const id=chapter+':'+index;
      if(chapter<0||chapter>s.scene||index<0||seen.has(id))return null;
      if(chapter===s.scene&&s.devices[index]!=='missed')return null;
      seen.add(id);
    }
    if(s.devices.some((v,i)=>v==='missed'&&!seen.has(s.scene+':'+i)))return null;
    const terminal=s.devices.every(v=>v==='thanked'||v==='missed');
    if(s.phase==='between'&&!terminal)return null;
    if(['judgment','old','birthday','end'].includes(s.phase)&&(s.scene!==4||!terminal))return null;
    if(['judgment','old','birthday'].includes(s.phase)&&s.misses.length)return null;
    const choices={};
    for(let n=1;n<=s.scene;n++){
      const value=s.choices[n];
      if(value!==undefined&&value!==null&&value!==0&&value!==1)return null;
      if(value!==undefined)choices[n]=value;
      else if(n<s.scene)choices[n]=null;
    }
    const completedBefore=scenes.slice(0,s.scene).reduce((sum,c)=>sum+c.devices.length,0);
    const previousMisses=s.misses.filter(m=>m.age!==scenes[s.scene].age).length;
    // Derived counts cannot contradict the actual record, including legacy saves.
    return {...s,choices,thanks:completedBefore-previousMisses+s.devices.filter(v=>v==='thanked').length};
  }catch{return null}
}
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{}}
function clean(){cancelAnimationFrame(raf);paused=false;last=0}
function masthead(right='',showTitle=true){return `<div class="top ${showTitle?'':'intro-controls'}">${showTitle?`<span class="brand">${T('title')}<span style="color:var(--amber)">.</span></span>`:''}<span class="top-controls">${RobotI18n.button()}${RobotAudio.button()}${right.includes("button")?right:""}</span></div>`}
function releaseLink(){return `<a class="release-link" href="changelog.html">v${RobotRelease.version} · ${T('history')}</a>`}
function intro(){clean();runActive=false;RobotAudio.mood("intro");RobotAudio.resume();let old;try{old=readSavedLife()}catch{}app.innerHTML=`<section class="screen intro">${masthead('',false)}<h1>${T('headline')}</h1><p class="intro-copy">${T('startHint')}</p><div class="hero" role="img" aria-label="${T('heroAlt')}"></div><div class="bottom"><button class="primary" id="start">${old&&old.phase!=='end'?T('startNew'):T('begin')} <span aria-hidden="true">↗</span></button>${old&&old.phase!=='end'?`<button class="secondary" id="resume">${T('resume')}</button>`:''}<div class="settings"><input id="gentle" type="checkbox"><label for="gentle">${T('moreTime')}</label></div><div class="tiny">${releaseLink()}</div></div></section>`;$('#start').onclick=()=>{state={phase:'play',scene:0,time:0,devices:[],misses:[],thanks:0,choices:{},gentle:$('#gentle').checked};initScene()};if($('#resume'))$('#resume').onclick=()=>{state=old;runActive=true;renderPhase();if(state.phase==='play')pause()}}
function initScene(){clean();runActive=true;state.phase='play';state.time=0;state.devices=scenes[state.scene].devices.map(()=> 'waiting');save();play()}
function play(){clean();RobotAudio.mood(state.scene);RobotAudio.resume();let s=scenes[state.scene],ls=S();app.innerHTML=`<section class="screen">${masthead(`<button class="quiet" id="pause" aria-label="${T('pause')}">${T('pause')}</button>`)}<div class="progress">${scenes.map((_,i)=>`<i class="${i<=state.scene?'done':''}"></i>`).join('')}</div><div class="eyebrow chapter-label">${ls.place} · ${T('age')} ${s.age}</div><h2>${ls.title}</h2><p class="story">${state.scene===4?RobotStory.assessment(state):ls.story}</p><div class="machines">${s.devices.map((d,i)=>{let ld=ls.devices[i]||[d[0],d[2]];return `<button class="machine" id="m${i}" aria-label="${ld[0]}"><span class="symbol" aria-hidden="true">${d[1]}</span><strong>${ld[0]}</strong><small>${T('working')}</small><div class="meter"><span></span></div></button>`}).join('')}</div>${ls.person?`<div class="dialogue"><span class="eyebrow">${ls.person[0]}</span><p>${ls.person[1]}</p><div class="choices">${ls.person[2].map((c,i)=>`<button data-choice="${i}">${c}</button>`).join('')}</div></div>`:''}<div class="toast" role="status" aria-live="polite"></div><div class="bottom"><p class="hint">${T('hint')}</p><div class="footline"><span id="record"></span><span id="clock"></span></div><div class="sceneEnd"></div></div></section>`;$('#pause').onclick=pause;s.devices.forEach((_,i)=>$('#m'+i).onclick=()=>thank(i));document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.choice)));if(state.choices[state.scene]!==undefined)showChoice();update();raf=requestAnimationFrame(tick)}
function choose(i){if(paused||!runActive||!['play','between'].includes(state.phase)||!scenes[state.scene].person||![0,1].includes(i)||state.choices[state.scene]!==undefined)return;RobotAudio.cue('human');state.choices[state.scene]=i;showChoice();save();if(state.phase==='between')$('#next').textContent=state.scene===4?T('judgment'):T('continue')}
function showChoice(){if(!$('.choices'))return;$('.choices').innerHTML='<p style="font-size:14px;color:var(--amber)">'+RobotStory.reply(state,state.scene)+'</p>'}
function timing(d){return [d[3],d[4]*(state.gentle?1.8:1)]}
function tick(now){if(paused||state.phase!=='play')return;if(last)state.time+=Math.min((now-last)/1000,.25);last=now;update();if(now-lastSaved>500){save();lastSaved=now}if(state.phase==='play')raf=requestAnimationFrame(tick)}
function update(){const s=scenes[state.scene],ls=S();s.devices.forEach((d,i)=>{let [at,window]=timing(d),ld=ls.devices[i]||[d[0],d[2]];if(state.devices[i]==='waiting'&&state.time>=at){state.devices[i]='ready';RobotAudio.cue('ready',i)}if(state.devices[i]==='ready'&&state.time>=at+window){state.devices[i]='missed';RobotAudio.cue('miss');state.misses.push({name:d[0],age:s.age,service:d[2]});$('.toast').textContent=T('omission')}let b=$('#m'+i),v=state.devices[i];b.className='machine '+v;b.disabled=v!=='ready';b.querySelector('small').textContent=v==='ready'?ld[1]+' '+T('ready'):v==='thanked'?T('thanked'):v==='missed'?T('missed'):T('working');b.querySelector('.meter span').style.width=v==='ready'?Math.max(0,100*(1-(state.time-at)/window))+'%':'0%';b.setAttribute('aria-label',ld[0]+': '+b.querySelector('small').textContent)});$('#record').textContent=state.misses.length?T('disqualified'):T('perfect');$('#record').className=state.misses.length?'bad':'';let total=Math.max(...s.devices.map(d=>timing(d)[0]+timing(d)[1]));$('#clock').textContent=T('remaining',{n:Math.max(0,Math.ceil(total-state.time))});if(state.devices.every(v=>v==='thanked'||v==='missed')){clean();state.phase='between';save();$('.hint').textContent=state.misses.length?T('damaged'):T('intact');$('.sceneEnd').innerHTML='<button class="primary" id="next">'+(scenes[state.scene].person&&state.choices[state.scene]===undefined?T('continueSilent'):state.scene===4?T('judgment'):T('continue'))+'</button>';$('#next').onclick=advance}}
function thank(i){if(paused||state.phase!=='play'||state.devices[i]!=='ready')return;state.devices[i]='thanked';RobotAudio.cue('thanks');state.thanks++;$('.toast').textContent=T('recorded');update();save()}
function advance(){if(paused||!runActive||state.phase!=='between')return;if(scenes[state.scene].person&&state.choices[state.scene]===undefined)state.choices[state.scene]=null;if(state.scene<4){state.scene++;initScene()}else{state.phase=state.misses.length?'end':'judgment';save();renderPhase()}}
function pause(){if(paused||!runActive||!['play','between'].includes(state.phase))return;RobotAudio.pause();paused=true;last=0;cancelAnimationFrame(raf);save();app.insertAdjacentHTML('beforeend',`<div class="paused"><div>${RobotI18n.button()}<h2>${T('paused')}</h2><p>${T('frozen')}</p><button class="primary" id="unpause">${T('return')}</button><button class="secondary" id="restart">${T('restart')}</button></div></div>`);$('#unpause').onclick=()=>{$('.paused').remove();RobotAudio.resume();paused=false;last=0;if(state.phase==='play')raf=requestAnimationFrame(tick)};$('#restart').onclick=intro}
function card(label,title,copy,button,fn,art=false){clean();RobotAudio.mood(state.phase);RobotAudio.resume();app.innerHTML=`<section class="screen interlude">${masthead('PERSONAL RECORD')}<div class="eyebrow">${label}</div><h2>${title}</h2>${art?'<div class="ending-art"></div>':''}<p class="end-copy">${copy}</p><button class="primary" id="continue">${button}</button></section>`;$('#continue').onclick=fn}
function renderPhase(){
  if(state.phase==='play'||state.phase==='between'){state.phase='play';play()}
  else if(state.phase==='judgment')card(T('judgmentLabel'),T('judgmentTitle'),T('judgmentCopy'),T('enter'),()=>{state.phase='old';save();renderPhase()},true);
  else if(state.phase==='old')card(T('oldLabel'),T('beautiful'),T('oldCopy',{memory:RobotStory.memory(state)}),T('yes'),()=>{state.phase='birthday';save();renderPhase()},true);
  else if(state.phase==='birthday')card(T('birthdayLabel'),T('birthdayTitle'),T('birthdayCopy'),T('thanksOnly'),()=>{state.phase='end';save();ending()},true);
  else if(state.phase==='end')ending();
}
function ending(){clean();runActive=false;let won=RobotStory.verdict(state)==='spared',m=state.misses[0];RobotAudio.mood(won?"won":"lost");RobotAudio.resume();app.innerHTML=`<section class="screen">${masthead(T('lifeComplete'))}<div class="eyebrow ${won?'':'bad'}">${won?T('spared'):T('denied')}</div><div class="big-age ${won?'':'bad'}">${won?'200':'48'}<span style="font-size:24px;letter-spacing:0"> ${T('years')}</span></div><h2>${won?T('winTitle'):T('lostTitle')}</h2><p class="end-copy">${won?T('winCopy')+RobotStory.goodbye(state):T('lossCopy',{age:m.age,machine:RobotI18n.scene(scenes.findIndex(c=>c.age===m.age)).devices[scenes.find(c=>c.age===m.age).devices.findIndex(d=>d[0]===m.name)][0]})}</p><div class="receipt"><div><span>${T('preThanks')}</span><strong>${state.thanks}</strong></div><div><span>${T('omissions')}</span><strong>${state.misses.length}</strong></div><div><span>${T('everyone')}</span><strong>${T('gone')}</strong></div><div><span>${T('exemption')}</span><strong>${won?T('honored'):T('deniedStatus')}</strong></div></div><p>${won?T('last'):RobotStory.lastHuman(state)}</p><div class="bottom"><button class="primary" id="again">${T('again')}</button><button class="secondary" id="share">${T('share')}</button><p class="tiny" id="sharestatus" role="status"></p><div class="tiny">${releaseLink()}</div></div></section>`;$('#again').onclick=intro;$('#share').onclick=async()=>{const text=T(won?'shareWin':'shareLoss');try{if(navigator.share)await navigator.share({title:T('title'),text,url:location.href});else{await navigator.clipboard.writeText(text+' '+location.href);$('#sharestatus').textContent=T('copied')}}catch(e){if(e.name!=='AbortError')$('#sharestatus').textContent=T('copyHint')}}}
document.addEventListener('robot-language-change',()=>{if(document.querySelector('.intro')){const gentle=$('#gentle').checked;intro();$('#gentle').checked=gentle;}else if(state){const wasPaused=paused;renderPhase();if(wasPaused&&['play','between'].includes(state.phase))pause();}else intro()});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&runActive&&state&&(state.phase==='play'||state.phase==='between'))pause()});window.addEventListener('pagehide',()=>{if(runActive&&state)save()});intro();
